package com.prima.factory.config; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.crypto.bcrypt.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain;
@Configuration public class SecurityConfig { @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean SecurityFilterChain chain(HttpSecurity h)throws Exception{return h.csrf(c->c.ignoringRequestMatchers("/api/v1/auth/**","/ws/**")).authorizeHttpRequests(a->a.requestMatchers("/api/v1/auth/**","/actuator/health","/swagger-ui/**","/v3/api-docs/**","/ws/**").permitAll().anyRequest().authenticated()).build();} }
